result:
**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so a token where `exp === currentTime` passes the check — it should be `<=`.

**A second issue:** `jwt.verify()` already throws `JsonWebTokenError` or `TokenExpiredError` on invalid/expired tokens, so the manual `exp` check is both redundant *and* wrong — it runs on an already-verified token, creating a gap where the library accepted it but your check would normally catch it (and vice versa at the boundary).

The clean fix is to remove the manual check entirely and let `jwt.verify` own expiry validation, then handle errors by type:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // jwt.verify enforces exp with correct <= semantics internally
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    if (err instanceof jwt.TokenExpiredError) {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err instanceof jwt.JsonWebTokenError) {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // Unexpected errors (e.g. missing JWT_SECRET) shouldn't leak details
    next(err);
  }
}

module.exports = authMiddleware;
```

**Key changes:**
- Removed the manual `exp` check — `jwt.verify` uses `exp <= now` correctly per the JWT spec (RFC 7519 §4.1.4)
- Split error handling into `TokenExpiredError` vs `JsonWebTokenError` for distinct client messages
- Unknown errors (e.g. misconfigured `JWT_SECRET`) are forwarded to Express's error handler via `next(err)` rather than swallowed or exposed as "Invalid token"
